INSERT INTO "public"."general_operation" VALUES
	(1, 6, 81, '- For commercial orchard preparation, refer to operation Table ref{ODG00} <br><br> - Adequately moisten planting-hole cite{ferreeApplesBotanyProduction2003} and Fertigation soon after planting cite{robinsonCropLoadManagement2008}.<br> - Use stakes or trellis to support trees to prevent branch breakage and find structures via cite{ferreeApplesBotanyProduction2003}.'),
	(2, 7, 81, 'For typical orchard management strategies for young trees, refer to operation Table ref{ODG01}.'),
	(3, 8, 81, 'For typical orchard management strategies for mature trees, refer to operation Table ref{ODG02}.'),
	(4, 10, 81, '- For suggested opperation, refer to Table ref{OAR00}'),
	(5, 10, 81, '- For suggested opperation, refer to Table ref{OAR00}');
