INSERT INTO "public"."measurement_category" VALUES
	(12, 'climate-weather-and-environmental-condit', 'Climate & weather', 'Climate, Weather And Environmental Conditions', 101),
	(13, 'phenology-timing-and-visual-records', 'Phenology & timing', 'Phenology, Timing And Visual Records', 102),
	(14, 'orchard-layout-establishment-and-tree-si', 'Layout & establishment', 'Orchard Layout, Establishment And Tree Size', 103),
	(15, 'soil-and-root-zone-water', 'Soil & root-zone water', 'Soil And Root-Zone Water', 104),
	(16, 'tree-vigour-trunk-and-shoot-growth', 'Vigour & shoot growth', 'Tree Vigour, Trunk And Shoot Growth', 105),
	(17, 'canopy-and-light', 'Canopy & light', 'Canopy And Light', 106),
	(18, 'leaf-measurements', 'Leaves', 'Leaf Measurements', 107),
	(19, 'tree-water-status', 'Tree water status', 'Tree Water Status', 108),
