	(25, 'fruit-internal-chemical-traits-and-matur', 'Fruit chemistry & maturity', 'Fruit Internal Chemical Traits And Maturity', 114),
	(26, 'postharvest-storage-and-quality-retentio', 'Postharvest storage', 'Postharvest Storage And Quality Retention', 115),
	(27, 'ipdm-senescence-and-tree-decline', 'IPDM & senescence', 'IPDM, Senescence And Tree Decline', 116);
INSERT INTO "public"."measurement_protocol" VALUES
	(4, 'Harvest date; DAFB; harvest maturity class', 'Phenology, Timing And Visual Records', 13, NULL, 'OAR00-93', 'Harvest date is recorded at picking. DAFB ais calculated from the site-specific full-bloom date. Harvest maturity class is assigned from starch index, firmness, SSC, background colour, internal ethylene and IAD measured on a defined fruit sample.', 'Table S34 (2026 revision)', NULL, NULL),
	(11, 'Tree age; tree size', 'Orchard Layout, Establishment And Tree Size', 14, NULL, 'ODG00-03', 'Tree age is calculated from planting date. Tree size is derived from trunk diameter, tree height or canopy dimensions measured on the same tagged tree across observations.', 'Table S34 (2026 revision)', NULL, NULL),
	(12, 'Graft-union height; planting distance; tree density; row orientation', 'Orchard Layout, Establishment And Tree Size', 14, NULL, 'ODG00-03', 'Graft-union height, row spacing and within-row spacing are measured with a tape or survey pole. Planting density is calculated from tree spacing. Row orientation is measured as field bearing.', 'Table S34 (2026 revision)', NULL, 'survey pole; tape'),
	(5, 'Root-zone soil sample', 'Soil And Root-Zone Water', 15, NULL, 'NDG00; ODG00-03', 'Composite root-zone soil sample is prepared from multiple subsamples collected at specified feeder-root depth within each sampling unit. Sampling depth, trunk distance, subsample number and sampling date are reported.', 'Table S34 (2026 revision)', NULL, NULL),
	(6, 'Soil pH; soil EC; main soil nutrient status', 'Soil And Root-Zone Water', 15, NULL, 'NDG00; ODG00-03', 'Soil pH and EC are measured from composite root-zone soil samples using the stated soil-water or soil-extract procedure. Main soil nutrients are quantified from the same sampling unit using the stated extraction, digestion and elemental-analysis method.', 'Table S34 (2026 revision)', NULL, NULL),
	(7, 'Soil moisture; soil-water potential / tension', 'Soil And Root-Zone Water', 15, NULL, 'NDG00; ODG00-03; OAR10-93', 'Volumetric soil water content is measured with calibrated capacitance or TDR probes installed at representative root-zone depths. Soil-water potential is measured with tensiometers or matric-potential sensors installed at documented depths and distances from emitters or tree trunks.', 'Table S34 (2026 revision)', NULL, 'capacitance; TDR probe'),
	(75, 'Postharvest mass loss; water-loss rate', 'Postharvest Storage And Quality Retention', 26, NULL, 'OAR82; postharvest', 'Postharvest mass loss or water-loss rate is measured by repeatedly weighing the same fruit during storage or shelf life and expressing mass loss relative to initial mass.', 'Table S34 (2026 revision)', NULL, NULL),
	(1, 'Weather-station measurements', 'Climate, Weather And Environmental Conditions', 12, NULL, 'NDG00; ODG00-03; OAR00-93', 'Air temperature and relative humidity are recorded with calibrated shielded sensors at the orchard weather station; VPD and dew point are calculated from the same records. Wind speed, wind gust and wind direction are recorded with a calibrated anemometer and wind vane. Rainfall and rainfall intensity are recorded with a calibrated rain gauge. Solar radiation is recorded with a pyranometer; PAR/PPFD is measured with a quantum sensor or linear ceptometer above, below or within the canopy. Leaf wetness duration is recorded with leaf-wetness sensors positioned at representative canopy locations. Photoperiod is calculated from site coordinates and date.', 'Table S34 (2026 revision)', NULL, 'orchard weather station'),
	(37, 'Temperature-derived heat and chill metrics', 'Climate, Weather And Environmental Conditions', 12, NULL, 'OAR00-04', 'Growing degree days, heat units, chilling hours, chill units, and chill portions are calculated from orchard or nearby temperature records using the specified thermal or chill model, with model parameters, temperature thresholds or base temperature, time step, and accumulation period reported.', 'Table S34 (2026 revision)', NULL, NULL),
	(3, 'Soil/root-zone temperature', 'Soil And Root-Zone Water', 15, NULL, 'NDG00; ODG00-03; OAR00-93', 'Soil or root-zone temperature is continuously recorded using temperature probes installed at fixed depths within the root zone, with probe depth, horizontal distance from the trunk, sensor location, and logging interval documented.', 'Table S34 (2026 revision)', NULL, 'temperature probe'),
	(22, 'Trunk diameter; trunk circumference; TCSA', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, 'ODG03', 'Trunk circumference is measured with a tape around a smooth trunk surface 20-50 cm above the graft union. Trunk diameter is measured at the same position with calipers or derived from circumference. TCSA is derived from trunk circumference or diameter.', 'Table S34 (2026 revision)', NULL, 'calipers'),
	(19, 'Shoot length; shoot elongation rate; terminal growth cessation', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, 'NDG01-04; OAR30-39; OAR79', 'Shoot length is measured repeatedly from the shoot base to the terminal tip on tagged shoots. Shoot elongation rate is calculated from repeated shoot-length measurements over a defined interval, and terminal growth cessation is recorded when extension stops.', 'Table S34 (2026 revision)', NULL, 'tape'),
	(13, 'Main-stem node number; flowering-node position', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, 'NDG01-03', 'Main-stem node number and flowering-node position are counted sequentially from a fixed basal node using one numbering convention for all trees and dates.', 'Table S34 (2026 revision)', NULL, NULL),
	(15, 'Thorn presence; adventitious-root presence; side-shoot angle', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, 'NDG01-03', 'Thorniness and adventitious rooting are scored at fixed plant positions using apple or apple-rootstock descriptor definitions. Side-shoot angle is measured with an inclinometer, protractor or calibrated image.', 'Table S34 (2026 revision)', NULL, NULL),
	(26, 'Canopy height; width; depth; area; volume', 'Canopy And Light', 17, NULL, 'ODG01-02; OAR10-82', 'Canopy height, width and depth are measured with a tape, survey pole, laser distance meter, calibrated image or point cloud. Canopy area and volume are calculated from measured dimensions or segmented 3D imagery using the stated geometric model.', 'Table S34 (2026 revision)', NULL, 'survey pole; tape'),
	(27, 'Leaf area index; leaf area density', 'Canopy And Light', 17, 'direct/reconstructed', 'ODG02; OAR10-82', 'Direct LAI is calculated from measured total leaf area relative to ground area. Optical or image-derived LAI is estimated from canopy-analyser readings or standardized hemispherical images, with view position, sky condition and calculation method reported.', 'Table S34 (2026 revision)', NULL, 'leaf-area meter'),
	(30, 'Light interception; within-canopy PAR distribution', 'Canopy And Light', 17, NULL, 'ODG02; OAR10-82', 'Light interception is calculated from simultaneous above- and below-canopy PAR. Within-canopy PAR distribution is measured with a quantum sensor or ceptometer at defined canopy positions and times of day.', 'Table S34 (2026 revision)', '1 - I_{below}/I_{above}', 'linear ceptometer; ceptometer'),
	(14, 'Leaf morphology, colour and expansion', 'Leaf Measurements', 18, NULL, 'NDG01-03', 'Leaf area, length, width, volume, colour and expansion are measured on defined leaf classes and canopy positions with a leaf-area meter, calibrated image, scan or colour instrument. Leaf serration and shape are scored using apple descriptor definitions.', 'Table S34 (2026 revision)', NULL, 'scanned'),
	(17, 'Leaf number; dry mass; water content; LMA', 'Leaf Measurements', 18, NULL, 'NDG01-03; OAR10-82', 'Leaf number is counted on a defined shoot, branch or canopy unit. Leaf dry mass and water content are calculated from paired fresh and oven-dry mass measured on the same leaf sample. LMA is calculated from one-sided leaf area and dry mass.', 'Table S34 (2026 revision)', NULL, 'oven-dry'),
	(43, 'Leaf nutrient content', 'Leaf Measurements', 18, NULL, 'OAR10-93', 'Recently mature leaves are collected using a standardized apple leaf-sampling protocol. Leaf N, P, K, Ca, Mg and micronutrients are measured from dried ground leaf tissue by the stated digestion, extraction and elemental-analysis method.', 'Table S34 (2026 revision)', NULL, NULL),
	(41, 'Leaf chlorophyll; SPAD; carotenoids', 'Leaf Measurements', 18, NULL, 'OAR10-82', 'SPAD or other optical chlorophyll index is measured on recently mature apple leaves with the meter model and leaf position reported. Destructive chlorophylls and carotenoids are quantified from a fixed leaf mass or area by solvent extraction followed by spectrophotometry or chromatography.', 'Table S34 (2026 revision)', NULL, 'SPAD meter'),
	(44, 'Photosynthesis; stomatal conductance; transpiration', 'Leaf Measurements', 18, NULL, 'OAR10-93', 'Net photosynthesis, stomatal conductance and transpiration are measured on defined leaves with an infrared gas analyser under stated chamber CO2, PAR, flow rate and leaf-temperature conditions.', 'Table S34 (2026 revision)', NULL, 'infrared gas analyser'),
	(46, 'Chlorophyll fluorescence; Fv/Fm', 'Leaf Measurements', 18, NULL, 'OAR80-93', 'Chlorophyll fluorescence is measured on defined leaves with a PAM fluorometer after a stated dark-adaptation period. F0 and Fm are recorded from dark-adapted leaves, and Fv/Fm is calculated as (Fm - F0 )/Fm.', 'Table S34 (2026 revision)', NULL, 'PAM fluorometer'),
	(47, 'Stem water potential', 'Tree Water Status', 19, NULL, 'OAR10-82', 'Stem water potential is measured with a Scholander-type pressure chamber on lower-canopy interior apple leaves near the trunk or scaffold branches. Leaves are bagged before excision, with bag type, equilibration duration, measurement time and pressure units reported.', 'Table S34 (2026 revision)', NULL, 'pressure chamber'),
	(48, 'Trunk water potential', 'Tree Water Status', 19, NULL, 'OAR30-82', 'Trunk water potential is recorded continuously with embedded microtensiometers installed in the apple trunk at a stated height relative to the rootstock or graft union. Predawn, midday, daily minimum, daily mean or daily range values are derived from the logged time series.', 'Table S34 (2026 revision)', NULL, 'tensiometer; microtensiometer'),
	(49, 'Canopy temperature; Tc - Ta', 'Tree Water Status', 19, NULL, 'OAR10-82', 'Canopy temperature is measured with an infrared radiometer or calibrated thermal camera viewing a defined apple canopy zone. Tc - Ta is calculated from simultaneous canopy temperature and nearby air temperature, with the aggregation window stated.', 'Table S34 (2026 revision)', NULL, 'infrared radiometer; thermal camera'),
	(35, 'Bud count; buds per tree, shoot or TCSA', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR00-04; ODG01-02', 'Bud number is counted on a defined apple unit, such as tree, branch, 1-year-old shoot, spur, terminal shoot or lateral shoot, and reported with the denominator and bud type.', 'Table S34 (2026 revision)', NULL, 'calipers'),
	(52, 'Flower-bud histological stage', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR40-70', 'Flower-bud histological stage is determined from fixed, sectioned buds examined with calibrated light microscopy or SEM. Meristem dimensions and appendage number are recorded from the same anatomical reference plane.', 'Table S34 (2026 revision)', NULL, NULL),
	(59, 'Bourse-bud, fruit or leaf phytohormones', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR60-62', 'Phytohormones are quantified from apple bourse buds, fruit flesh, seeds, fruit diffusates or leaves collected on a defined tissue and date basis. Samples are frozen or preserved as specified and analysed by targeted chromatography or mass spectrometry with internal standards and compound-specific calibration.', 'Table S34 (2026 revision)', NULL, 'UHPLC-MS/MS; LC-MS/MS; HPLC'),
	(51, 'Flower count; flower-cluster count; flowers per cluster', 'Flowering And Pollination', 21, NULL, 'OAR40-70', 'Flower clusters and open flowers are counted on fixed trees, branches or shoots. Flowers per cluster are calculated from the same counted clusters, with king and lateral flowers separated when relevant.', 'Table S34 (2026 revision)', NULL, NULL),
	(33, 'Flowering intensity; bloom percentage; return bloom', 'Flowering And Pollination', 21, NULL, 'ODG02-03; OAR40-59', 'Flowering intensity is derived from blossom-cluster counts or a fixed bloom scale on tagged trees. Bloom percentage is calculated from the same tagged flower population. Return bloom is measured on the same trees in the following season.', 'Table S34 (2026 revision)', NULL, NULL),
	(57, 'Flowering overlap; effective pollination period', 'Flowering And Pollination', 21, NULL, 'OAR50-59', 'Flowering overlap is calculated from cultivar bloom windows. Effective pollination period is determined from timed controlled-pollination or from stigmatic receptivity, pollen-tube growth rate and ovule longevity observations.', 'Table S34 (2026 revision)', NULL, NULL),
	(55, 'Pollen viability; in-vitro germination; pollen-tube progression', 'Flowering And Pollination', 21, NULL, 'OAR50-59', 'Pollen viability is measured with a stated staining assay. In-vitro germination is measured on defined apple pollen medium under stated incubation temperature and duration. Pollen-tube progression is measured in controlled-pollinated pistils stained with aniline blue and examined by fluorescence microscopy.', 'Table S34 (2026 revision)', NULL, 'fluorescence microscopy; aniline blue'),
	(31, 'Crop load; fruit number per tree; fruit number per TCSA', 'Fruit Set, Yield And Crop Load', 22, NULL, 'ODG02-03; OAR40-82', 'Crop load is calculated as fruit number per tree or as fruit number divided by same-tree TCSA. Blossom-cluster density is calculated from blossom-cluster count divided by same-tree TCSA or branch cross-sectional area.', 'Table S34 (2026 revision)', NULL, NULL),
	(32, 'Annual yield; cumulative yield; yield efficiency', 'Fruit Set, Yield And Crop Load', 22, NULL, 'ODG02-03; OAR82', 'Yield is measured as total harvested fruit mass per tree or area. Cumulative yield is calculated by summing annual yield across years, and yield efficiency is calculated from yield divided by same-tree TCSA.', 'Table S34 (2026 revision)', NULL, NULL),
	(60, 'Fruit size; diameter; length; width; fresh mass; growth rate', 'Fruit External Traits', 23, NULL, 'OAR70-82', 'Fruit diameter, length and width are measured with calipers on a defined fruit sample. Fruit fresh mass is measured with a balance. Fruit growth rate is calculated from repeated tagged-fruit measurements.', 'Table S34 (2026 revision)', NULL, 'calipers; balance'),
	(68, 'Skin colour; L* a* b* ; hue; chroma; blush coverage', 'Fruit External Traits', 23, NULL, 'OAR80-82', 'Fruit skin colour is measured at standardized fruit positions with a calibrated colorimeter or spectrophotometer and reported as L* a* b* , hue or chroma. Blush coverage is quantified from standardized fruit images or a defined visual scale.', 'Table S34 (2026 revision)', NULL, 'colorimeter; spectrophotometer'),
	(69, 'Peel chlorophyll; carotenoids; anthocyanins', 'Fruit External Traits', 23, NULL, 'OAR80-82', 'Fruit peel chlorophylls, carotenoids and anthocyanins are quantified from a fixed peel area or mass by solvent extraction followed by spectrophotometry or HPLC. Peel zone, sun exposure class and fresh- or dry-mass basis are reported.', 'Table S34 (2026 revision)', NULL, 'HPLC'),
	(71, 'IAD', 'Fruit External Traits', 23, NULL, 'OAR80-82', 'IAD is measured at standardized equatorial positions with a DA meter as A670 - A720 , with fruit side, number of readings per fruit and harvest/storage date reported.', 'Table S34 (2026 revision)', 'I_{AD} = A_{670} - A_{720}', 'DA meter'),
	(72, 'Fruit surface temperature; near-surface tissue temperature', 'Fruit External Traits', 23, NULL, 'OAR70-82', 'Fruit surface temperature is measured with calibrated thermal images or a recording thermocouple attached to individual fruit. Near-surface tissue temperature is measured with a probe inserted to a fixed tissue depth.', 'Table S34 (2026 revision)', NULL, 'thermal image'),
	(63, 'Fruit firmness', 'Fruit Internal Physical And Anatomical Traits', 24, NULL, 'OAR80-82', 'Fruit firmness is measured on peeled equatorial sides with an 11.1-mm Magness-Taylor penetrometer probe or an equivalent texture analyser, with probe size, peel removal, fruit temperature and number of readings per fruit reported.', 'Table S34 (2026 revision)', NULL, 'penetrometer'),
	(67, 'Fruit dry matter; water content; density', 'Fruit Internal Physical And Anatomical Traits', 24, NULL, 'OAR70-82', 'Fruit dry matter and water content are calculated from paired fresh and oven-dry mass. Fruit density is calculated from fruit mass and measured volume, with tissue basis and drying endpoint reported.', 'Table S34 (2026 revision)', NULL, 'oven-dry'),
	(61, 'Fruit cortex cell traits', 'Fruit Internal Physical And Anatomical Traits', 24, NULL, 'OAR70-79', 'Fruit cortex cell number, cell diameter and projected cell area are measured from calibrated histological images of defined cortex sections; sampling date, anatomical plane and image-calibration method are reported.', 'Table S34 (2026 revision)', NULL, NULL),
	(64, 'SSC; titratable acidity; juice pH', 'Fruit Internal Chemical Traits And Maturity', 25, NULL, 'OAR70-82', 'Soluble solids concentration is measured from expressed juice with a calibrated refractometer. Titratable acidity is measured by NaOH titration to a stated endpoint and expressed as malic-acid equivalent. Juice pH is measured with a calibrated pH meter.', 'Table S34 (2026 revision)', NULL, 'refractometer'),
	(66, 'Starch-iodine pattern index', 'Fruit Internal Chemical Traits And Maturity', 25, NULL, 'OAR80-82', 'Harvest starch index is determined from an equatorial fruit section stained with iodine-KI and scored against a cultivar-specific chart; cultivar chart, score scale and sampling date are reported.', 'Table S34 (2026 revision)', NULL, 'iodine'),
	(62, 'Glucose; fructose; sucrose; sorbitol', 'Fruit Internal Chemical Traits And Maturity', 25, NULL, 'OAR70-82', 'Fruit glucose, fructose, sucrose and sorbitol are quantified from defined fruit tissue by HPLC or validated enzymatic sugar assays. Tissue region, fresh- or dry-mass basis, extraction solvent and calibration method are reported.', 'Table S34 (2026 revision)', NULL, NULL),
	(73, 'Fruit mineral nutrients', 'Fruit Internal Chemical Traits And Maturity', 25, NULL, 'OAR70-82', 'Fruit N is measured from dried ground fruit tissue by Kjeldahl digestion or equivalent N analysis. Fruit P, K, Ca, Mg and micronutrients are measured after acid digestion by AAS, ICP-OES or equivalent elemental analysis.', 'Table S34 (2026 revision)', NULL, 'AAS; ICP; Kjeldahl'),
	(70, 'Internal ethylene concentration; ethylene production; respiration rate', 'Fruit Internal Chemical Traits And Maturity', 25, NULL, 'OAR80-82', 'Internal ethylene concentration is measured from core-cavity gas by gas chromatography. Ethylene production or respiration rate is measured from headspace accumulation over a known fruit mass and time, with CO2 quantified by gas chromatography or infrared gas analysis.', 'Table S34 (2026 revision)', NULL, 'GC-FID'),
	(76, 'Disease incidence; disease severity; disease risk', 'IPDM, Senescence And Tree Decline', 27, NULL, 'ODG01-03; OAR10-93', 'Disease incidence is calculated as affected units divided by assessed units. Disease severity is scored with a disease-specific scale. Apple scab, fire blight and powdery mildew risk are derived from stated weather-model inputs.', 'Table S34 (2026 revision)', NULL, NULL),
	(77, 'Pest abundance; trap catch; pest-damaged fruit', 'IPDM, Senescence And Tree Decline', 27, NULL, 'ODG01-03; OAR10-82', 'Mite eggs, motile mites, aphid colonies, codling-moth trap catch and pest-damaged fruit are determined from standardized leaf, shoot, fruit or trap sampling and expressed per defined sampling unit.', 'Table S34 (2026 revision)', NULL, 'pheromone trap'),
	(78, 'Leaf discoloration; leaf fall', 'IPDM, Senescence And Tree Decline', 27, NULL, 'OAR90-93', 'Leaf discoloration and leaf fall are quantified repeatedly on the same canopy population using BBCH senescence stages or percentage affected/fallen foliage.', 'Table S34 (2026 revision)', NULL, NULL),
	(79, 'Senescing-leaf physiology and chemistry', 'IPDM, Senescence And Tree Decline', 27, NULL, 'OAR90-93', 'Senescing-leaf gas exchange and Fv/Fm are measured with the same IRGA and PAM protocols used for mature leaves. Senescing-leaf chlorophyll, nutrients, soluble sugars, starch, protein, amino acids or H2O2 are quantified only when the stated biochemical assay and tissue basis are reported.', 'Table S34 (2026 revision)', NULL, 'IRGA'),
	(83, 'Whole-tree decline; survival; mortality; internal trunk necrosis', 'IPDM, Senescence And Tree Decline', 27, NULL, 'ODG03', 'Whole-tree decline, survival and mortality are scored repeatedly on the same tagged trees using a stated decline-severity scale or incidence definition. Internal trunk necrosis is measured as necrotic area divided by total cross-sectional wood area on destructive trunk sections.', 'Table S34 (2026 revision)', NULL, NULL),
	(86, 'Frost-risk inputs; heat-stress inputs', 'Climate, Weather And Environmental Conditions', 12, NULL, NULL, 'Frost-risk input is derived from phenological stage, measured or forecast air temperature, wet-bulb temperature, wind condition and local critical-damage temperature. Heat-stress and sunburn-risk input is derived from radiation, air temperature, wind condition and fruit or canopy temperature.', 'Table S34 (2026 revision)', NULL, NULL),
	(87, 'Irrigation volume; irrigation depth; irrigation frequency', 'Soil And Root-Zone Water', 15, NULL, NULL, 'Irrigation volume is measured with a calibrated flow meter or irrigation controller record. Irrigation depth is calculated from applied volume and irrigated area, and irrigation frequency is recorded from event dates or controller logs.', 'Table S34 (2026 revision)', NULL, NULL),
	(88, 'Tree vigour; growth rate; terminal growing point', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, NULL, 'Tree vigour and growth rate are derived from repeated trunk, shoot and canopy measurements on tagged trees. Terminal growing-point status is recorded on the same tagged shoots.', 'Table S34 (2026 revision)', NULL, NULL),
	(89, 'Optical and spectral estimates', 'Canopy And Light', 17, NULL, NULL, 'Vegetation indices, canopy-vigour estimates and fruit or leaf optical indices are derived from calibrated RGB, multispectral, hyperspectral or LiDAR data and validated against the stated reference measurement.', 'Table S34 (2026 revision)', NULL, NULL),
	(90, 'Sap flow', 'Tree Water Status', 19, NULL, NULL, 'Sap flow is measured continuously with a heat-pulse or thermal-dissipation probe installed in apple trunk sapwood. Probe depth, azimuth, heated/reference spacing, logging interval, sapwood-area scaling and calibration equation are reported.', 'Table S34 (2026 revision)', NULL, NULL),
	(91, 'Fruit set; fruitlet retention; fruitlet abscission; fruit drop', 'Fruit Set, Yield And Crop Load', 22, NULL, NULL, 'Fruit set, fruitlet retention, abscission and drop are calculated from retained fruitlets relative to the initial number of tagged flowers or clusters. The same tagged units and counting dates are used across the observation period.', 'Table S34 (2026 revision)', NULL, NULL),
	(92, 'Fruit shape; symmetry', 'Fruit External Traits', 23, NULL, NULL, 'Fruit shape index and symmetry are calculated from length, width, diameter or calibrated image measurements taken on the same defined fruit sample.', 'Table S34 (2026 revision)', NULL, NULL),
	(93, 'Russet; sunburn; cracking; lenticel appearance; blemishes; pest or disease damage', 'Fruit External Traits', 23, NULL, NULL, 'Fruit surface defects are scored as incidence, severity or affected surface area on a defined fruit sample using a visual scale, imaging method or pest/disease diagnosis protocol.', 'Table S34 (2026 revision)', NULL, NULL),
	(94, 'Seed number; seed development; seed maturity', 'Fruit Internal Physical And Anatomical Traits', 24, NULL, NULL, 'Seed number is counted from a defined fruit sample. Seed development and maturity are scored with a stated visual, anatomical or developmental scale.', 'Table S34 (2026 revision)', NULL, NULL),
	(95, 'Storage temperature; relative humidity; O2; CO2; storage duration', 'Postharvest Storage And Quality Retention', 26, NULL, NULL, 'Storage temperature, relative humidity, oxygen, carbon dioxide and storage duration are recorded with storage-room sensors or lot-level storage records. Storage atmosphere and shelf-life transfer date are reported.', 'Table S34 (2026 revision)', NULL, NULL),
	(96, 'Postharvest firmness, SSC and acidity retention', 'Postharvest Storage And Quality Retention', 26, NULL, NULL, 'Postharvest quality retention is calculated from repeated firmness, SSC and acidity measurements on the same storage lot or fruit sample using the same methods as harvest quality measurements.', 'Table S34 (2026 revision)', NULL, NULL),
	(97, 'Storage disorders; shelf life', 'Postharvest Storage And Quality Retention', 26, NULL, NULL, 'Shrivel, bitter pit, storage rot, superficial scald, internal browning and shelf life are assessed as incidence, severity or time-to-threshold on defined fruit lots after storage and shelf-life periods.', 'Table S34 (2026 revision)', NULL, NULL),
	(98, 'Weed cover; groundcover status; beneficial organisms', 'IPDM, Senescence And Tree Decline', 27, NULL, NULL, 'Weed cover, species composition and groundcover status are assessed by quadrat, transect or image-based sampling. Natural enemy abundance and predator:prey ratio are determined from standardized visual or trap sampling.', 'Table S34 (2026 revision)', NULL, NULL),
	(10, 'Soil texture, bulk density, porosity, saturated hydraulic conductivity and penetration resistance', 'Soil And Root-Zone Water', 15, NULL, 'ODG00-03', 'Soil texture, bulk density, porosity, hydraulic conductivity and penetration resistance are measured with standard NRCS field and laboratory procedures.', 'Paper + authoritative protocol', NULL, NULL),
	(16, 'Leaf epidermal cell area/number, stomatal density, trichome density and leaf thickness', 'Leaf Measurements', 18, NULL, 'NDG01-03; OAR10-82', 'Epidermal cell size, stomatal/trichome density and leaf thickness are measured from calibrated microscopic images of fully expanded leaves.', 'Source paper protocol', NULL, NULL),
	(18, 'Phase-related phenolic markers (phloridzin, myricitrin, caffeic acid)', 'Leaf Measurements', 18, NULL, 'NDG01-03', 'Phloridzin, myricitrin and caffeic acid are quantified from defined tissues by HPLC using analytical standards.', 'Source paper protocol', NULL, 'HPLC'),
	(20, 'Root length, surface area, mean/maximum diameter and volume', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, 'NDG01; ODG03', 'Washed roots are scanned against a contrasting background and root length, area, diameter and volume are obtained by root-image analysis.', 'Source paper protocol', NULL, 'root-image analysis; scanned'),
	(21, 'Primary-root count; fine/medium/coarse root length; root dry mass; root-system width/depth/projected area', 'Tree Vigour, Trunk And Shoot Growth', 16, NULL, 'ODG03', 'Excavated roots are counted, separated into diameter classes, scanned for dimensions and oven-dried for dry mass.', 'Source paper protocol', NULL, 'scanned'),
	(23, 'Effective rooting depth and root water potential', 'Soil And Root-Zone Water', 15, NULL, 'ODG01-03; OAR50-82', 'Effective rooting depth is obtained from depth-resolved root observations; root water potential is measured on sampled roots with the cited pressure-potential method.', 'Source paper protocol', NULL, NULL),
	(24, 'Fine- and coarse-root starch', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR01-04', 'Fine and coarse roots are separated by diameter class, dried and ground, and starch is measured after extraction and hydrolysis.', 'Source paper protocol', NULL, NULL),
	(53, 'Pollinator visitation rate and flower-standardized visitation', 'Flowering And Pollination', 21, NULL, 'OAR50-59', 'Pollinator visitation is measured as flower visits recorded during fixed timed observations on a known number of open flowers.', 'Source paper protocol', NULL, NULL),
	(54, 'Pollen load on flower visitors', 'Flowering And Pollination', 21, NULL, 'OAR50-59', 'Pollen load is measured by removing pollen from captured flower visitors and counting grains microscopically.', 'Source paper protocol', NULL, NULL),
	(99, 'Phenological image; visual stage record', 'Phenology, Timing And Visual Records', 13, NULL, 'OAR00-95', 'Stage images are captured from fixed tree, shoot, bud, flower, fruit or canopy viewpoints and linked to the observation date, sample unit and stage code.', 'Table S34 (2026 revision)', NULL, NULL),
	(100, 'Phenological event date; BBCH code; DOY; DAFB', 'Phenology, Timing And Visual Records', 13, NULL, 'OAR00-95', 'Phenological event dates and BBCH stages are recorded from repeated apple observations. DOY and DAFB are calculated from the observation date and site-specific full-bloom date.', 'Table S34 (2026 revision)', NULL, NULL),
	(36, 'Bud size; fresh mass; dry mass; water content', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR00-04', 'Bud length, width, or diameter is measured using calipers or calibrated digital images. Bud fresh mass is measured immediately after sampling or preparation to minimise water loss. Bud dry mass is determined after freeze drying or oven drying to constant mass. Bud water content is calculated from paired fresh and dry masses.', 'Table S34 (2026 revision)', NULL, 'oven-dry'),
	(39, 'Bud or dormant-shoot carbohydrate reserves', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR00-04', 'Sucrose, glucose, fructose, and sorbitol are quantified from apple bud or dormant shoot tissues using enzymatic assays or high performance liquid chromatography (HPLC). Starch is determined from the insoluble pellet remaining after soluble sugar extraction, following enzymatic hydrolysis with amyloglucosidase. Sorbitol is quantified using a sorbitol-specific enzymatic assay or a validated chromatographic method such as HPLC.', 'Table S34 (2026 revision)', NULL, NULL),
	(38, 'Chilling requirement; budbreak percentage under forcing', 'Bud, Dormancy And Reserves', 20, NULL, 'OAR00-04', 'Chilling requirement is determined by exposing apple buds, excised shoots or branches, cuttings, or potted trees to defined chill accumulation, followed by forcing under controlled conditions and assessment of budbreak response. Budbreak percentage is calculated as the number of broken buds divided by the total number of buds of the same bud type within the defined sample unit, using a stated phenological criterion for budbreak, such as the corresponding BBCH stage.', 'Table S34 (2026 revision)', NULL, NULL);
INSERT INTO "public"."operation" VALUES
	(1, 6, 81, 'Involves adding topsoil to flatter or uniformly shaped ground', 'Modify Landscape', 'Levelling', 'confirmed'),
	(2, 6, 81, 'Establish the orchard parallel to natural contour of the land', 'Modify Landscape', 'Contouring', 'confirmed'),
	(3, 6, 81, 'Create stepped ground only considered when other soil and water conservation methods are insufficient', 'Modify Landscape', 'Terracing', 'confirmed'),
	(5, 6, 81, 'Find practical information in the article cite{schwabSoilWaterConservation1982}', 'Modify Landscape', 'Modifying Drainage', 'confirmed'),
	(6, 6, 81, 'Adjust soil pH using liming material for neutralization and material like elemental sulfur for acidification, based on soil test result.', 'Apply Material to Adjust Soil Condition', 'Liming/Acidifying materials', 'confirmed'),
	(7, 6, 81, 'Apply hay, straw, woodchips and manure at 30–60 t/ha and mix into the root zone.', 'Apply Material to Adjust Soil Condition', 'Organic material', 'confirmed'),
	(8, 6, 6, 'Apply nutrient like phosphorous and potassium based on soil test', 'Apply Material to Adjust Soil Condition', 'Fertilizer', 'confirmed'),
	(9, 6, 81, 'Typically executed to about 20 cm depth below ground. Deeper ploughing up to 35–40 cm is possible, but not recommended.', 'Perform Tillage', 'Ploughing', 'confirmed'),
	(10, 6, 231, 'Apply chemical biocides if needed, especially for replant sites cite{parkerHighDensityApple1998}', 'Disease management', 'Fumigate', 'confirmed'),
	(11, 6, 148, 'Utilize drippers, sprinklers, or pipes depending on orchard requirements.', 'Irrigation', 'Pre-plant irrigation system setup', 'confirmed'),
	(12, 7, 81, 'No crop in second year for lower density orchard; Control crop load at 4-6 fruits per square cm trunk cross-sectional area (TCSA) depending on variety cite{robinsonCropLoadManagement2008}', 'Thinning', 'Fruit load management', 'confirmed'),
	(15, 7, 81, 'Manage leader development by removing competing shoots and new shoots below the leader when they reach 2-5 cm, but not recommended for low-vigour trees cite{ferreeApplesBotanyProduction2003}; Bending, scoring and ringing can be applied to regulate tree growth if flowering is postponed cite{ferreeApplesBotanyProduction2003}; Control shoots growth of leader shoot with an incremental increase: 12-24 inches in first year, 30-36 inches in second and third years, and 18 inches in fourth year cite{robinsonCropLoadManagement2008}.', 'Pruning & Training', 'Leader management', 'confirmed'),
	(16, 7, 246, 'Apply before bud break in early spring based on soil test cite{howFertilizeApple2023}; Recommendations available via guide cite{2023IntegratedOrchard2023}.', 'Nutrient management', 'Fertilization', 'confirmed'),
	(17, 7, 6, 'According to goals, practical recommendations during different stages via cite{2023IntegratedOrchard2023}.', 'Plant growth regulator', '', 'confirmed'),
	(18, 7, 6, 'Use of PGRs in non-bearing trees', 'Plant growth regulator', '', 'confirmed'),
	(21, 7, 81, 'Use reflective films and shading such as coloured net; Bagging is also a common management strategy to protect fruit from sunburn and environmental damage.', 'Environmental stress management', 'Light & heat protection', 'confirmed'),
	(22, 7, 81, 'Guides for mitigating orchard environmental stress: hail, bushfires, drought, and wildlife. Includes bird protection, critical temperature charts, and sunburn prevention practices.', 'Environmental stress management', 'Extreme weather and animal protection', 'confirmed'),
	(23, 7, 81, 'Refer to the strategy outlined in the manual for monitoring duration and frequency, symptom descriptions, and appropriate actions. Practical recommendations are available for different stages based on crop goals and observations.', 'IPDM', 'Monitoring and action thresholds', 'confirmed'),
	(24, 8, 81, 'Remove buds, flowers, or fruits manually, mechanically, or chemically, depending on the method. This operation generally occurs once per season, with supplementary hand thinning later if the effect of initial thinning on fruit size or return bloom is not sufficient cite{stoverMethodAssessingRelationship2001}; Control 4-6 fruits per square cm of trunk cross-sectional area (TCSA), varying by variety cite{robinsonCropLoadManagement2008}.', 'Thinning', 'Fruit load management', 'confirmed'),
	(25, 8, 81, 'Remove shoots or limbs to maintain canopy within space during the dormant and summer seasons annually. See different pruning plans at cite{ferreeApplesBotanyProduction2003}. In larger orchards, pruning may be scheduled every second or third year to manage costs cite{ferreeApplesBotanyProduction2003}.', 'Pruning & Training', 'Canopy management', 'confirmed'),
	(26, 8, 71, 'Apply once in the spring and once in the autumn after fruiting cite{howFertilizeApple2023}; Integrated Orchard Management Guide for Commercial Apples in the Southeast, 2023 cite{2023IntegratedOrchard2023}.', 'Nutrient management', 'Seasonal fertilization', 'confirmed'),
	(27, 8, 71, 'Apply plant growth regulator to adjust the growth and characteristics of tree and fruit as necessary. For practical recommendation tailored to different developmental stages, refer to cite{2023IntegratedOrchardManagement2023}.', 'Plant growth regulator', '', 'confirmed'),
	(28, 8, 71, 'The irrigation schedule is based on thresholds or indexes determined by the method or simulation model specific to field, accounting for weather, soil and plant status cite{ferreeApplesBotanyProduction2003} Refer to cite{bolandGuideBestPractice2002} for maintaining soil moisture tension between 8 and 40 kPa, except dormancy period. In drought conditions, it is advisable to irrigate even in winter cite{ferreeApplesBotanyProduction2003}. Mature trees may require more frequent irrigation cite{dzikitiEstimatingWaterRequirements2018}.', 'Irrigation', 'Mature orchard watering', 'confirmed'),
	(30, 8, 81, 'Up to six cultivations per season may be required; Herbicide spraying requires 200-400L per ha.', 'Orchard floor management', 'Cultivation practice', 'confirmed'),
	(31, 8, 81, 'Herbicides spraying require 200-400l per ha of material to be effective and the water volume varies with the herbicide type cite{ferreeApplesBotanyProduction2003}', 'Orchard floor management', 'Weed control', 'confirmed'),
	(14, 7, 81, 'Select appropriate pollinizer trees and ensure sufficient pollen availability; Use of honeybees is recommended for pollination; Avoid using insecticides during flowering to protect pollinators; Use of pheromone traps to monitor pest populations and reduce pesticide use.', 'Pruning & Training', 'Pollination', 'confirmed'),
	(33, 8, 116, 'Refer to monitoring strategy with frequency, symptom description, and appropriate actions.', 'IPDM', 'Monitoring & intervention', 'confirmed'),
	(34, 8, 81, 'Use reflective films and shading such as coloured net; Bagging is also a common management strategy to protect fruit from sunburn and environmental damage.', 'Environmental stress management', 'Light & heat protection', 'confirmed'),
	(35, 8, 81, 'Guides for mitigating orchard environmental stress: hail, bushfires, drought, and wildlife. Includes bird protection, critical temperature charts, and sunburn prevention practices.', 'Environmental stress management', 'Extreme weather and animal protection', 'confirmed'),
