INSERT INTO "public"."stage" VALUES
	(1, 'NDG00', 'Seed Germination', 'Emergence of the seedling from seed, ending with established cotyledons and first leaves.', NULL),
	(2, 'NDG01', 'Juvenile Period', 'Vegetative phase before the tree is able to flower, lasting 4 to 12 years depending on cultivar.', NULL),
	(3, 'NDG02', 'Transition Period', 'Juvenile-to-adult phase change in which reproductive competence is acquired.', NULL),
	(4, 'NDG03', 'Reproductive Phase', 'Adult phase with regular flowering and fruiting.', NULL),
	(5, 'NDG04', 'Aging', 'Progressive decline in vegetative and reproductive performance.', NULL),
	(6, 'ODG00', 'Planting Tree', 'Initial phase of planting orchard trees, including rootstock preparation and grafting.', NULL),
	(7, 'ODG01', 'Young Tree', 'Early growth phase where trees establish roots and vegetative structures.', NULL),
	(8, 'ODG02', 'Mature Tree', 'Productive phase with active fruiting and full canopy development.', NULL),
	(9, 'ODG03', 'End of Productive Life', 'Decline phase marked by reduced vigor and fruit yield.', NULL),
	(11, 'OAR00-00', 'Para-dormancy', 'Dormancy controlled by internal conditions with carbohydrate buildup.', NULL),
	(12, 'OAR00-01', 'Endo-dormancy', 'Winter dormancy stage that requires chilling accumulation to break.', NULL),
	(13, 'OAR00-02', 'Eco-dormancy', 'Dormancy stage limited by external environmental conditions.', NULL),
	(31, 'OAR50-00', 'Pollination', 'Transfer of pollen grains between flowers.', NULL),
	(32, 'OAR50-01', 'Fertilization', 'Union of gametes resulting in zygote formation.', NULL),
	(33, 'OAR50-02', 'Fruit Set', 'Formation of fruit following successful fertilisation.', NULL),
	(37, 'OAR(60-62)', 'Flower Bud Formation for Next Season', 'Development of floral meristems for the following season.', NULL),
	(38, 'OAR60', 'Flower Induction', 'Initial physiological commitment to floral formation.', NULL),
	(39, 'OAR61', 'Flower Initiation', 'Early morphological changes indicating floral development.', NULL),
	(40, 'OAR62', 'Bud Differentiation', 'Complex differentiation within the floral bud structure.', NULL),
	(53, 'OAR82-postharvest', 'Post-harvest and Storage', 'Fruit after picking: cooling, controlled-atmosphere storage, storage disorders and rots.', NULL),
	(43, 'OAR70-00', 'Fruit Cell Division', 'Cell multiplication contributing to fruit growth.', NULL),
	(44, 'OAR70-01', 'Fruit Cell Enlargement', 'Cell expansion and volume increase.', NULL),
	(10, 'OAR00', 'Dormancy', 'Temporary suspension of visible growth with changes in carbohydrate, starch, and soluble sugar content.', 'BBCH00'),
	(15, 'OAR01', 'Beginning of Leaf Bud Swelling', 'Stage where bud scales elongate and lighten, preparing for break.', 'BBCH01'),
	(19, 'OAR10', 'Mouse-ear Stage', 'Rapid leaf unfolding and expansion phase.', 'BBCH10'),
	(20, 'OAR11', 'First Leaves Unfolded', 'Rapid leaf unfolding and expansion phase.', 'BBCH11'),
	(21, 'OAR12', 'More Leaves Unfolded', 'Rapid leaf unfolding and expansion phase.', 'BBCH15'),
	(24, 'OAR40', 'Inflorescence Bud Swelling', 'Stage where floral buds swell prominently.', 'BBCH51'),
	(25, 'OAR42', 'Bud Burst', 'Emergence of green leaf tips and visible flowers.', 'BBCH53'),
	(26, 'OAR43', 'Mouse-ear Stage', 'Petal elongation and sepals opening just before flowering.', 'BBCH54'),
	(27, 'OAR44', 'Flower Buds Visible', 'Petal elongation and sepals opening just before flowering.', 'BBCH55'),
	(30, 'OAR50', 'First Flowers Open', 'Opening of first flowers in the orchard.', 'BBCH60'),
	(34, 'OAR55', 'Full Flowering; At Least 50% of Flowers Open', 'Peak flowering period with maximum open blooms.', 'BBCH65'),
	(35, 'OAR57', 'Flowers Fading', 'Petal fall indicating flowering completion.', 'BBCH67'),
	(36, 'OAR59', 'End of Flowering', 'Petal fall indicating flowering completion.', 'BBCH69'),
	(42, 'OAR70', 'Beginning of Fruit Development', 'Rapid fruit expansion and growth.', NULL),
	(45, 'OAR71', 'Fruit Size Up to 10 mm; First Fruit Fall', 'Initial drop of unviable or excess fruitlets.', 'BBCH71'),
	(46, 'OAR72', 'Fruit Size Up to 20 mm', 'Subsequent natural thinning of fruits.', 'BBCH72'),
	(48, 'OAR73', 'Second Fruit Fall', 'Cessation of shoot elongation.', 'BBCH73'),
	(58, 'OAR94', 'All Leaves Fallen', 'Completion of leaf fall and onset of dormancy.', 'BBCH97'),
	(57, 'OAR93', '50% of Leaves Discoloured', 'Midway point of leaf discoloration.', 'BBCH95'),
	(56, 'OAR92', 'Beginning of Leaf Fall', 'Start of significant leaf drop.', 'BBCH93'),
	(55, 'OAR91', 'Leaves Begin to Discolour', 'Initial color change in leaves.', 'BBCH92'),
	(28, 'OAR47', 'Hollow Ball Stage', 'Flowers form a hollow ball shape at stage culmination.', 'BBCH59'),
	(16, 'OAR02', 'End of Leaf Bud Swelling', 'Stage where bud scales elongate and lighten, preparing for break.', 'BBCH03'),
	(17, 'OAR03', 'Beginning of Bud Break', 'Appearance of green leaf tips indicating bud break.', 'BBCH07'),
	(59, 'OAR04', 'Green Leaf Tips About 5 mm Above Bud Scales', 'Green leaf tips extend about 5 mm beyond the bud scales.', 'BBCH09'),
	(60, 'OAR13', 'First Leaves Fully Expanded', 'The first leaves of the season reach full expansion.', 'BBCH19'),
	(61, 'OAR30', 'Beginning of Shoot Growth', 'Shoot elongation begins.', 'BBCH31'),
	(62, 'OAR41', 'End of Inflorescence Bud Swelling', 'Inflorescence bud swelling is complete.', 'BBCH52'),
	(63, 'OAR45', 'Green Bud Stage', 'Flower buds are green and still closed.', 'BBCH56'),
	(64, 'OAR46', 'Pink Bud Stage', 'Petals elongate and sepals open just before flowering.', 'BBCH57'),
	(65, 'OAR51', 'Beginning of Flowering', 'The first flowers of the block are open.', 'BBCH61'),
	(66, 'OAR74', 'Fruit Diameter Up to 40 mm; T-stage', 'Fruit reaches about 40 mm diameter, the T-stage of fruit development.', 'BBCH74'),
	(14, 'OAR(01-04)', 'Bud Development', 'Progressive development of buds from swelling to bud break.', 'BBCH01-09'),
	(29, 'OAR(50-59)', 'Flowering', 'Progressive flower bloom with overlapping phases.', 'BBCH60-69'),
	(41, 'OAR(70-79)', 'Fruit Development', 'Fruit growth phase with size increase and physiological changes.', 'BBCH71-79'),
	(18, 'OAR(10-13)', 'Leaf Development', 'Rapid leaf unfolding and expansion phase.', 'BBCH10-19'),
	(22, 'OAR(30-39)', 'Shoot Development', 'Shoot elongation following a sigmoid growth pattern.', 'BBCH31-39'),
	(23, 'OAR(40-47)', 'Inflorescence Emergence', 'Floral bud development culminating in visible flowers.', 'BBCH51-59'),
	(50, 'OAR80', 'Beginning of Ripening', 'Initial stages of fruit coloration and ripening.', 'BBCH81'),
	(47, 'OAR90', 'Shoot Growth Completed; Terminal Bud Developed', 'Cessation of shoot elongation.', 'BBCH91'),
	(52, 'OAR81', 'Advanced Ripening', 'Harvest-ready stage of fruits.', 'BBCH85'),
	(67, 'OAR82', 'Fruit Ripe for Picking', 'Fruit reaches the maturity at which it is picked.', 'BBCH87'),
	(49, 'OAR(80-82)', 'Maturity of Fruit and Seed', 'Final ripening stage for fruit and seeds.', 'BBCH81-87'),
	(54, 'OAR(91-94)', 'Senescence', 'Progressive leaf senescence and drop.', 'BBCH92-97');
INSERT INTO "public"."stage_transition" VALUES
	(1, 'transition', 'NDG00', 'NDG01', 'Established seedling with sustained juvenile vegetative growth.', 'No universal numerical cut-off.'),
	(2, 'transition', 'NDG01', 'NDG02', 'Juvenile-to-adult phase transition begins.', 'Approximately 77 main-stem nodes.'),
	(3, 'transition', 'NDG02', 'NDG03', 'Reproductive competence and regular flowering are established.', 'Approximately 77-122 nodes; adult reference >122 nodes.'),
	(4, 'transition', 'NDG03', 'NDG04', 'Persistent decline in vegetative and reproductive performance.', 'No universal numerical cut-off.'),
	(5, 'transition', 'ODG00', 'ODG01', 'Planting and orchard establishment are completed.', 'Event-defined transition.'),
	(6, 'transition', 'ODG01', 'ODG02', 'Regular flowering and managed production are established.', 'Approximately sixth year; canopy values are system-specific references.'),
	(7, 'transition', 'ODG02', 'ODG03', 'Sustained loss of vigour, productivity or tree health.', 'No universal TCSA, yield or canopy cut-off.'),
	(8, 'transition', 'OAR00', 'OAR01-04', 'Visible bud swelling after dormancy release.', 'Approximately 800-1200 CU as a cultivar-dependent reference.'),
	(9, 'transition', 'OAR01-04', 'OAR10-13', 'Visible leaf emergence after bud break.', 'BBCH09: leaf tips about 5 mm; BBCH10: about 10 mm.'),
	(10, 'transition', 'OAR10-13', 'OAR30-39', 'Current-season shoot elongation becomes evident.', 'No universal LAI or shoot-length boundary.'),
	(11, 'stage_progression', NULL, 'OAR30-39', 'Shoot development progression.', 'BBCH35: about 50% final shoot length; BBCH39: about 90%.'),
	(12, 'transition', 'OAR40-45', 'OAR50-59', 'First flower opens.', 'BBCH61: about 10% open; BBCH65: about 50% open.'),
	(13, 'transition', 'OAR50-59', 'OAR70-79', 'Retained fruitlets enter sustained growth.', 'No universal fruit-set percentage.'),
	(14, 'stage_progression', NULL, 'OAR60-62', 'Flower-bud induction, initiation and differentiation are identified microscopically.', 'No universal numerical exit threshold.'),
	(15, 'transition', 'OAR70-79', 'OAR80-82', 'Ripening begins as fruit approaches final size.', 'BBCH75: about 50% final fruit size; BBCH81: beginning of ripening.'),
	(16, 'transition', 'OAR80-82', 'OAR90-93', 'Fruit maturity and leaf senescence are assessed separately.', 'No single numerical boundary.'),
	(17, 'transition', 'OAR90-93', 'OAR00', 'Leaf discoloration and leaf fall progress toward dormancy.', 'BBCH95: about 50% leaves discoloured; BBCH97: all leaves fallen.');
